-- Replace costly per-update JSON virtual-table probes with conservative scalar
-- exception detection. Escapes/repeated key text may produce false positives;
-- those documents use the safe exception path, not an incomplete index.
CREATE TABLE IF NOT EXISTS friendbook_cf_user_follow_membership (
 member TEXT NOT NULL, kind TEXT NOT NULL, source INTEGER NOT NULL CHECK(source IN (0,1)), path TEXT NOT NULL,
 PRIMARY KEY(member,kind,source,path)
) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS idx_cf_user_follow_by_path ON friendbook_cf_user_follow_membership(path,source,kind);
CREATE TABLE IF NOT EXISTS friendbook_cf_user_follow_index_state (id INTEGER PRIMARY KEY CHECK(id=1),ready INTEGER NOT NULL CHECK(ready=1));
DELETE FROM friendbook_cf_user_follow_index_state;
DELETE FROM friendbook_cf_user_follow_membership;
DROP TRIGGER IF EXISTS cf_user_follow_1_insert;
DROP TRIGGER IF EXISTS cf_user_follow_1_update;
DROP TRIGGER IF EXISTS cf_user_follow_1_delete;
DROP TRIGGER IF EXISTS cf_user_follow_0_insert;
DROP TRIGGER IF EXISTS cf_user_follow_0_update;
DROP TRIGGER IF EXISTS cf_user_follow_0_delete;


INSERT OR IGNORE INTO friendbook_cf_user_follow_membership SELECT j.value,'followers',1,d.path FROM friendbook_cf_firestore_documents d, json_each(CASE WHEN json_type(d.document_json,'$.followers')='array' THEN json_extract(d.document_json,'$.followers') ELSE '[]' END) j WHERE d.parent_path='users' AND NOT (instr(d.document_json,char(92))>0 OR length(d.document_json)-length(replace(d.document_json,'"followers"',''))>length('"followers"') OR length(d.document_json)-length(replace(d.document_json,'"following"',''))>length('"following"')) AND j.type='text';

INSERT OR IGNORE INTO friendbook_cf_user_follow_membership SELECT j.value,'following',1,d.path FROM friendbook_cf_firestore_documents d, json_each(CASE WHEN json_type(d.document_json,'$.following')='array' THEN json_extract(d.document_json,'$.following') ELSE '[]' END) j WHERE d.parent_path='users' AND NOT (instr(d.document_json,char(92))>0 OR length(d.document_json)-length(replace(d.document_json,'"followers"',''))>length('"followers"') OR length(d.document_json)-length(replace(d.document_json,'"following"',''))>length('"following"')) AND j.type='text';

INSERT OR IGNORE INTO friendbook_cf_user_follow_membership SELECT '','*',1,d.path FROM friendbook_cf_firestore_documents d WHERE d.parent_path='users' AND (instr(d.document_json,char(92))>0 OR length(d.document_json)-length(replace(d.document_json,'"followers"',''))>length('"followers"') OR length(d.document_json)-length(replace(d.document_json,'"following"',''))>length('"following"'));

CREATE TRIGGER IF NOT EXISTS cf_user_follow_1_insert AFTER INSERT ON friendbook_cf_firestore_documents WHEN NEW.parent_path='users' BEGIN
  INSERT OR IGNORE INTO friendbook_cf_user_follow_membership SELECT j.value,'followers',1,NEW.path FROM json_each(CASE WHEN json_type(NEW.document_json,'$.followers')='array' THEN json_extract(NEW.document_json,'$.followers') ELSE '[]' END) j WHERE NEW.parent_path='users' AND NOT (instr(NEW.document_json,char(92))>0 OR length(NEW.document_json)-length(replace(NEW.document_json,'"followers"',''))>length('"followers"') OR length(NEW.document_json)-length(replace(NEW.document_json,'"following"',''))>length('"following"')) AND j.type='text';
  INSERT OR IGNORE INTO friendbook_cf_user_follow_membership SELECT j.value,'following',1,NEW.path FROM json_each(CASE WHEN json_type(NEW.document_json,'$.following')='array' THEN json_extract(NEW.document_json,'$.following') ELSE '[]' END) j WHERE NEW.parent_path='users' AND NOT (instr(NEW.document_json,char(92))>0 OR length(NEW.document_json)-length(replace(NEW.document_json,'"followers"',''))>length('"followers"') OR length(NEW.document_json)-length(replace(NEW.document_json,'"following"',''))>length('"following"')) AND j.type='text';
  INSERT OR IGNORE INTO friendbook_cf_user_follow_membership SELECT '','*',1,NEW.path WHERE NEW.parent_path='users' AND (instr(NEW.document_json,char(92))>0 OR length(NEW.document_json)-length(replace(NEW.document_json,'"followers"',''))>length('"followers"') OR length(NEW.document_json)-length(replace(NEW.document_json,'"following"',''))>length('"following"'));
END;

CREATE TRIGGER IF NOT EXISTS cf_user_follow_1_update AFTER UPDATE ON friendbook_cf_firestore_documents WHEN (OLD.parent_path='users' OR NEW.parent_path='users') AND (OLD.parent_path IS NOT NEW.parent_path OR OLD.path IS NOT NEW.path OR (instr(OLD.document_json,char(92))>0 OR length(OLD.document_json)-length(replace(OLD.document_json,'"followers"',''))>length('"followers"') OR length(OLD.document_json)-length(replace(OLD.document_json,'"following"',''))>length('"following"')) IS NOT (instr(NEW.document_json,char(92))>0 OR length(NEW.document_json)-length(replace(NEW.document_json,'"followers"',''))>length('"followers"') OR length(NEW.document_json)-length(replace(NEW.document_json,'"following"',''))>length('"following"')) OR (NOT (instr(OLD.document_json,char(92))>0 OR length(OLD.document_json)-length(replace(OLD.document_json,'"followers"',''))>length('"followers"') OR length(OLD.document_json)-length(replace(OLD.document_json,'"following"',''))>length('"following"')) AND NOT (instr(NEW.document_json,char(92))>0 OR length(NEW.document_json)-length(replace(NEW.document_json,'"followers"',''))>length('"followers"') OR length(NEW.document_json)-length(replace(NEW.document_json,'"following"',''))>length('"following"')) AND (json_extract(OLD.document_json,'$.followers') IS NOT json_extract(NEW.document_json,'$.followers') OR json_type(OLD.document_json,'$.followers') IS NOT json_type(NEW.document_json,'$.followers') OR json_extract(OLD.document_json,'$.following') IS NOT json_extract(NEW.document_json,'$.following') OR json_type(OLD.document_json,'$.following') IS NOT json_type(NEW.document_json,'$.following')))) BEGIN
  DELETE FROM friendbook_cf_user_follow_membership WHERE path=OLD.path AND source=1 AND (NEW.parent_path<>'users' OR OLD.path IS NOT NEW.path OR (instr(NEW.document_json,char(92))>0 OR length(NEW.document_json)-length(replace(NEW.document_json,'"followers"',''))>length('"followers"') OR length(NEW.document_json)-length(replace(NEW.document_json,'"following"',''))>length('"following"')) OR kind='*' OR (kind='followers' AND member NOT IN (SELECT value FROM json_each(CASE WHEN json_type(NEW.document_json,'$.followers')='array' THEN json_extract(NEW.document_json,'$.followers') ELSE '[]' END) WHERE type='text')) OR (kind='following' AND member NOT IN (SELECT value FROM json_each(CASE WHEN json_type(NEW.document_json,'$.following')='array' THEN json_extract(NEW.document_json,'$.following') ELSE '[]' END) WHERE type='text')));
  INSERT OR IGNORE INTO friendbook_cf_user_follow_membership SELECT j.value,'followers',1,NEW.path FROM json_each(CASE WHEN json_type(NEW.document_json,'$.followers')='array' THEN json_extract(NEW.document_json,'$.followers') ELSE '[]' END) j WHERE NEW.parent_path='users' AND NOT (instr(NEW.document_json,char(92))>0 OR length(NEW.document_json)-length(replace(NEW.document_json,'"followers"',''))>length('"followers"') OR length(NEW.document_json)-length(replace(NEW.document_json,'"following"',''))>length('"following"')) AND j.type='text';
  INSERT OR IGNORE INTO friendbook_cf_user_follow_membership SELECT j.value,'following',1,NEW.path FROM json_each(CASE WHEN json_type(NEW.document_json,'$.following')='array' THEN json_extract(NEW.document_json,'$.following') ELSE '[]' END) j WHERE NEW.parent_path='users' AND NOT (instr(NEW.document_json,char(92))>0 OR length(NEW.document_json)-length(replace(NEW.document_json,'"followers"',''))>length('"followers"') OR length(NEW.document_json)-length(replace(NEW.document_json,'"following"',''))>length('"following"')) AND j.type='text';
  INSERT OR IGNORE INTO friendbook_cf_user_follow_membership SELECT '','*',1,NEW.path WHERE NEW.parent_path='users' AND (instr(NEW.document_json,char(92))>0 OR length(NEW.document_json)-length(replace(NEW.document_json,'"followers"',''))>length('"followers"') OR length(NEW.document_json)-length(replace(NEW.document_json,'"following"',''))>length('"following"'));
END;

CREATE TRIGGER IF NOT EXISTS cf_user_follow_1_delete AFTER DELETE ON friendbook_cf_firestore_documents WHEN OLD.parent_path='users' BEGIN
  DELETE FROM friendbook_cf_user_follow_membership WHERE path=OLD.path AND source=1;
END;

INSERT OR IGNORE INTO friendbook_cf_user_follow_membership SELECT j.value,'followers',0,d.path FROM friendbook_cf_documents d, json_each(CASE WHEN json_type(d.document_json,'$.followers')='array' THEN json_extract(d.document_json,'$.followers') ELSE '[]' END) j WHERE d.collection='users' AND NOT (instr(d.document_json,char(92))>0 OR length(d.document_json)-length(replace(d.document_json,'"followers"',''))>length('"followers"') OR length(d.document_json)-length(replace(d.document_json,'"following"',''))>length('"following"') OR length(d.document_json)-length(replace(d.document_json,'"fields"',''))>length('"fields"') OR json_type(d.document_json,'$.fields') IS 'object') AND j.type='text';

