INSERT OR IGNORE INTO friendbook_cf_user_follow_membership SELECT '','*',0,d.path FROM friendbook_cf_documents d WHERE d.collection='users' AND (instr(d.document_json,char(92))>0 OR length(d.document_json)-length(replace(d.document_json,'"followers"',''))>length('"followers"') OR length(d.document_json)-length(replace(d.document_json,'"following"',''))>length('"following"') OR length(d.document_json)-length(replace(d.document_json,'"fields"',''))>length('"fields"') OR json_type(d.document_json,'$.fields') IS 'object');

