END;

CREATE TRIGGER IF NOT EXISTS cf_user_follow_0_update AFTER UPDATE ON friendbook_cf_documents WHEN (OLD.collection='users' OR NEW.collection='users') AND (OLD.collection IS NOT NEW.collection OR OLD.path IS NOT NEW.path OR (instr(OLD.document_json,char(92))>0 OR length(OLD.document_json)-length(replace(OLD.document_json,'"followers"',''))>length('"followers"') OR length(OLD.document_json)-length(replace(OLD.document_json,'"following"',''))>length('"following"') OR length(OLD.document_json)-length(replace(OLD.document_json,'"fields"',''))>length('"fields"') OR json_type(OLD.document_json,'$.fields') IS 'object') IS NOT (instr(NEW.document_json,char(92))>0 OR length(NEW.document_json)-length(replace(NEW.document_json,'"followers"',''))>length('"followers"') OR length(NEW.document_json)-length(replace(NEW.document_json,'"following"',''))>length('"following"') OR length(NEW.document_json)-length(replace(NEW.document_json,'"fields"',''))>length('"fields"') OR json_type(NEW.document_json,'$.fields') IS 'object') OR (NOT (instr(OLD.document_json,char(92))>0 OR length(OLD.document_json)-length(replace(OLD.document_json,'"followers"',''))>length('"followers"') OR length(OLD.document_json)-length(replace(OLD.document_json,'"following"',''))>length('"following"') OR length(OLD.document_json)-length(replace(OLD.document_json,'"fields"',''))>length('"fields"') OR json_type(OLD.document_json,'$.fields') IS 'object') AND NOT (instr(NEW.document_json,char(92))>0 OR length(NEW.document_json)-length(replace(NEW.document_json,'"followers"',''))>length('"followers"') OR length(NEW.document_json)-length(replace(NEW.document_json,'"following"',''))>length('"following"') OR length(NEW.document_json)-length(replace(NEW.document_json,'"fields"',''))>length('"fields"') OR json_type(NEW.document_json,'$.fields') IS 'object') AND (json_extract(OLD.document_json,'$.followers') IS NOT json_extract(NEW.document_json,'$.followers') OR json_type(OLD.document_json,'$.followers') IS NOT json_type(NEW.document_json,'$.followers') OR json_extract(OLD.document_json,'$.following') IS NOT json_extract(NEW.document_json,'$.following') OR json_type(OLD.document_json,'$.following') IS NOT json_type(NEW.document_json,'$.following')))) BEGIN
  DELETE FROM friendbook_cf_user_follow_membership WHERE path=OLD.path AND source=0 AND (NEW.collection<>'users' OR OLD.path IS NOT NEW.path OR (instr(NEW.document_json,char(92))>0 OR length(NEW.document_json)-length(replace(NEW.document_json,'"followers"',''))>length('"followers"') OR length(NEW.document_json)-length(replace(NEW.document_json,'"following"',''))>length('"following"') OR length(NEW.document_json)-length(replace(NEW.document_json,'"fields"',''))>length('"fields"') OR json_type(NEW.document_json,'$.fields') IS 'object') OR kind='*' OR (kind='followers' AND member NOT IN (SELECT value FROM json_each(CASE WHEN json_type(NEW.document_json,'$.followers')='array' THEN json_extract(NEW.document_json,'$.followers') ELSE '[]' END) WHERE type='text')) OR (kind='following' AND member NOT IN (SELECT value FROM json_each(CASE WHEN json_type(NEW.document_json,'$.following')='array' THEN json_extract(NEW.document_json,'$.following') ELSE '[]' END) WHERE type='text')));
  INSERT OR IGNORE INTO friendbook_cf_user_follow_membership SELECT j.value,'followers',0,NEW.path FROM json_each(CASE WHEN json_type(NEW.document_json,'$.followers')='array' THEN json_extract(NEW.document_json,'$.followers') ELSE '[]' END) j WHERE NEW.collection='users' AND NOT (instr(NEW.document_json,char(92))>0 OR length(NEW.document_json)-length(replace(NEW.document_json,'"followers"',''))>length('"followers"') OR length(NEW.document_json)-length(replace(NEW.document_json,'"following"',''))>length('"following"') OR length(NEW.document_json)-length(replace(NEW.document_json,'"fields"',''))>length('"fields"') OR json_type(NEW.document_json,'$.fields') IS 'object') AND j.type='text';
