END;

CREATE TRIGGER IF NOT EXISTS cf_user_follow_0_delete AFTER DELETE ON friendbook_cf_documents WHEN OLD.collection='users' BEGIN
  DELETE FROM friendbook_cf_user_follow_membership WHERE path=OLD.path AND source=0;
END;

